CREATE TABLE IF NOT EXISTS gis_official_source_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text UNIQUE NOT NULL, authority_name text NOT NULL, source_title text NOT NULL, source_url text NOT NULL, hierarchy text NOT NULL, authority_level text NOT NULL, acquisition_status text NOT NULL DEFAULT 'DISCOVERED', artifact_sha256 text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_canonical_source_identity (source_key text PRIMARY KEY, source_registry_id uuid NOT NULL REFERENCES gis_official_source_registry(id), source_url text NOT NULL, authority_level text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inec_official_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_name text NOT NULL, source_url text NOT NULL UNIQUE, authority text NOT NULL, artifact_type text NOT NULL, retrieval_status text NOT NULL DEFAULT 'DISCOVERED', http_status integer, content_type text, byte_size bigint, sha256 text, storage_key text, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text, retrieved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), source_registry_id uuid, canonical_source_key text, provenance_status text NOT NULL DEFAULT 'PENDING', artifact_identity text);
CREATE UNIQUE INDEX IF NOT EXISTS inec_official_artifacts_sha256_uidx ON inec_official_artifacts(sha256) WHERE sha256 IS NOT NULL;
CREATE TABLE IF NOT EXISTS gis_exception_candidate_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL, candidate_source text NOT NULL, state_name text NOT NULL, lga_name text NOT NULL, candidate_area_code text, confidence numeric NOT NULL, status text NOT NULL DEFAULT 'CANDIDATE_ONLY', evidence_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_ward_evidence_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, source_name text NOT NULL, source_url text, evidence_type text NOT NULL, authority_level text NOT NULL DEFAULT 'UNVERIFIED', artifact_sha256 text, excerpt text, state_name text, lga_name text, ward_name text, ward_code text, geometry_verified boolean NOT NULL DEFAULT false, provenance_verified boolean NOT NULL DEFAULT false, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text, created_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_current_exception_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version text NOT NULL, source_feature_id uuid NOT NULL, target_feature_id uuid, state_code text, category text NOT NULL, status text NOT NULL DEFAULT 'OPEN', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id));
CREATE TABLE IF NOT EXISTS gis_exception_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL, reviewer_id text NOT NULL, decision text NOT NULL, rationale text NOT NULL, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_exception_promotion_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, evidence_attachment_id uuid, decision text NOT NULL, reason text NOT NULL, before_status text NOT NULL, after_status text NOT NULL, decided_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_evidence_conflicts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, evidence_a_id uuid NOT NULL, evidence_b_id uuid NOT NULL, conflict_reason text NOT NULL, authority_a text, authority_b text, provenance_a boolean NOT NULL DEFAULT false, provenance_b boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'REQUIRES_REVIEW', resolution_note text, resolved_by text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_match_id,evidence_a_id,evidence_b_id));
CREATE TABLE IF NOT EXISTS inec_live_api_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_source_key text NOT NULL, endpoint_path text NOT NULL, request_query jsonb NOT NULL, http_status integer NOT NULL, content_type text, byte_size integer NOT NULL, response_sha256 text, response_json jsonb, acquisition_status text NOT NULL, provenance_status text NOT NULL DEFAULT 'SOURCE_BOUND', acquired_at timestamptz NOT NULL DEFAULT now(), UNIQUE(canonical_source_key,endpoint_path,request_query));
CREATE TABLE IF NOT EXISTS inec_candidate_live_crosswalks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, state_id integer, lga_id integer, official_lga_name text, official_ward_count integer NOT NULL DEFAULT 0, lga_snapshot_id uuid, ward_snapshot_id uuid, match_status text NOT NULL DEFAULT 'CANDIDATE_MATCH_ONLY', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_match_id));
INSERT INTO gis_official_source_registry(id,source_key,authority_name,source_title,source_url,hierarchy,authority_level,acquisition_status,notes) VALUES('1a17203d-270d-475c-99ae-871d232397be','INEC-POLLING-UNIT-LOCATOR-2026','Independent National Electoral Commission (INEC)','INEC Polling Unit Locator 2026','https://cvr.inecnigeria.org/pu','State > LGA > Ward/Registration Area > Polling Unit','PRIMARY_OFFICIAL','DISCOVERED','Canonical source identity restored without asserting artifact acquisition or verification.') ON CONFLICT(source_key) DO UPDATE SET source_url=EXCLUDED.source_url,authority_level=EXCLUDED.authority_level,updated_at=now();
INSERT INTO gis_canonical_source_identity(source_key,source_registry_id,source_url,authority_level) SELECT source_key,id,source_url,authority_level FROM gis_official_source_registry WHERE source_key='INEC-POLLING-UNIT-LOCATOR-2026' ON CONFLICT(source_key) DO UPDATE SET source_registry_id=EXCLUDED.source_registry_id,source_url=EXCLUDED.source_url,authority_level=EXCLUDED.authority_level,updated_at=now();